from rcb_client import Robot
import numpy as np
r=Robot(); p=np.array(r.get_obs(cameras=[],video='none').meta['proprio']['now'][7:14],float)
ori=p[3:7]; dst=np.array([-.35,0,.30]); cur=p[:3]; n=int(np.ceil(np.linalg.norm(dst-cur)/.008)); a=np.column_stack([cur+(dst-cur)*t/n for t in range(1,n+1)]).T; rows=np.column_stack([a,np.tile(ori,(n,1))])
res=r.submit('ee_pose',rows,dt=.05,cameras=[],video='none',note='retreat for practice inspection'); print(res.meta['control_steps_chunk'],res.meta['proprio']['now'][7:10])
obs=r.get_obs(cameras=['practice_cam'],video='none'); from PIL import Image; Image.fromarray(obs.last['practice_cam']).save('/app/output/practice_clear.png')
PY",workdir:"/app",yield_time_ms:30000,max_output_tokens:1000});
